// =====================================================================
//  Fristberechnung Auskunftsersuchen (§ 161 StPO)  +  Handlungsbedarf
//
//  1:1 uebernommen aus der Pfaendungs-Fristueberwachung
//  ("Fristen berechnen (§ 840 ZPO)") - dieselbe Regel-Engine, zwei
//  Unterschiede:
//   - Die Frist kommt PRO FALL aus antwortfrist_tage (nicht fix 14),
//     falls kuenftige Auskunftsersuchen eine andere Frist vorschreiben.
//   - STATUS_ERLEDIGT nutzt 'Antwort versandt' statt 'Erklaerung versandt'.
//
//  Wochenend-/Feiertagsverschiebung bleibt als Annahme uebernommen -
//  ob sie fuer StPO-Ersuchen genauso gilt wie fuer ZPO-Fristen, ist
//  fachlich nicht geprueft (siehe Sticky Note "Offen fuer Legal").
//
//  RALPH-PROGRESS.md Iteration 3 (2026-08-28): Signal-Downgrade-Fix
//  nachgezogen, der im Pfaendungs-Node (§ 840 ZPO) bereits am 2026-08-27
//  angewendet wurde, hier aber trotz "1:1 uebernommen"-Kommentar fehlte -
//  ohne die zusaetzlichen Bedingungen konnte nach bereits gesendeter
//  Eskalation trotzdem noch eine niedrigerprioritaere erinnerung_2/
//  erinnerung_1 nachgereicht werden. Getestete Referenz jetzt in
//  feldmark_app/server/fristlogik.js - bei kuenftigen Aenderungen bitte
//  dort UND in beiden Code-Nodes synchron halten.
// =====================================================================

const VORLAUF_ERINNERUNG_2 = 3;
const VORLAUF_ESKALATION = 1;
const STATUS_ERLEDIGT = ['Antwort versandt', 'Abgeschlossen', 'Abgeschlossen mit Fristversaeumnis'];

// Feiertage werden berechnet, nicht gepflegt: eine feste 2026-Liste haette ab
// 1.1.2027 stillschweigend nur noch Wochenenden erkannt. Identisch zur
// Referenzkopie feldmark_app/server/fristlogik.js.
function ostersonntag(jahr) {
  const a = jahr % 19, b = Math.floor(jahr / 100), c = jahr % 100;
  const d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const monat = Math.floor((h + l - 7 * m + 114) / 31);
  const tag = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(Date.UTC(jahr, monat - 1, tag));
}
function feiertageFuer(jahr) {
  const o = ostersonntag(jahr);
  const rel = (n) => iso(addDays(o, n));
  return [`${jahr}-01-01`, rel(-2), rel(1), `${jahr}-05-01`, rel(39), rel(50),
          `${jahr}-10-03`, `${jahr}-12-25`, `${jahr}-12-26`];
}
function feiertageUm(datum) {
  const j = datum.getUTCFullYear();
  return [...feiertageFuer(j), ...feiertageFuer(j + 1)];
}

function toDate(s) { return new Date(String(s).slice(0, 10) + 'T00:00:00Z'); }
function iso(d) { return d.toISOString().slice(0, 10); }
function addDays(d, n) { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x; }
function istWerktag(d, feiertage) {
  const wd = d.getUTCDay();
  return wd !== 0 && wd !== 6 && !feiertage.includes(iso(d));
}
function naechsterWerktag(d) {
  const feiertage = feiertageUm(d);
  let x = new Date(d);
  while (!istWerktag(x, feiertage)) x = addDays(x, 1);
  return x;
}
function tageDiff(a, b) { return Math.round((a.getTime() - b.getTime()) / 86400000); }

const heute = new Date();
heute.setUTCHours(0, 0, 0, 0);

const out = [];

for (const item of $input.all()) {
  const f = item.json;

  // Leerlauf-Schutz: der Loader liefert bei null offenen Faellen mit
  // alwaysOutputData ein leeres Item. Ohne diesen Zweig wuerde toDate(undefined)
  // werfen und der Lauf schiene fehlgeschlagen, obwohl nichts zu tun war. So
  // laeuft das leere Item als 'keine' bis zum Abschluss-Knoten durch.
  if (!f.eingangsdatum) {
    out.push({ json: { ...f, aktion: 'keine', begruendung: 'Keine offenen Faelle - nichts zu tun.' } });
    continue;
  }

  const FRIST_TAGE = Number(f.antwortfrist_tage) || 14;

  const eingang = toDate(f.eingangsdatum);
  const fristRoh = addDays(eingang, FRIST_TAGE);
  const frist = naechsterWerktag(fristRoh);
  const restTage = tageDiff(frist, heute);

  let gesendet = f.erinnerungen_gesendet;
  if (typeof gesendet === 'string') {
    gesendet = gesendet.replace(/[{}"]/g, '').split(',').filter(Boolean);
  }
  if (!Array.isArray(gesendet)) gesendet = [];

  const erledigt = STATUS_ERLEDIGT.includes(f.status);

  let aktion = 'keine';
  let begruendung = '';

  if (erledigt) {
    aktion = 'keine';
    begruendung = 'Antwort bereits versandt — Fristueberwachung fuer diesen Fall beendet.';
  } else if (restTage < 0) {
    if (!gesendet.includes('fristversaeumnis')) {
      aktion = 'fristversaeumnis';
      begruendung = `Frist am ${iso(frist)} abgelaufen, Antwort nicht versandt.`;
    } else {
      aktion = 'keine';
      begruendung = `Frist am ${iso(frist)} abgelaufen, Fristversaeumnis bereits dokumentiert.`;
    }
  } else if (restTage <= VORLAUF_ESKALATION && !gesendet.includes('eskalation')) {
    aktion = 'eskalation';
    begruendung = `Noch ${restTage} Tag(e) bis Fristablauf, Antwort offen.`;
  } else if (restTage <= VORLAUF_ERINNERUNG_2 && !gesendet.includes('erinnerung_2') && !gesendet.includes('eskalation')) {
    aktion = 'erinnerung_2';
    begruendung = `Noch ${restTage} Tag(e) bis Fristablauf.`;
  } else if (!gesendet.includes('erinnerung_1') && !gesendet.includes('erinnerung_2') && !gesendet.includes('eskalation')) {
    aktion = 'erinnerung_1';
    begruendung = 'Fristbeginn — Fall zur Bearbeitung eingesteuert.';
  } else {
    aktion = 'keine';
    begruendung = `Noch ${restTage} Tag(e) Puffer, faellige Erinnerung bereits versandt.`;
  }

  out.push({
    json: {
      ...f,
      erinnerungen_gesendet: gesendet,
      fristende_roh: iso(fristRoh),
      fristende: iso(frist),
      fristende_verschoben: iso(frist) !== iso(fristRoh),
      rest_tage: restTage,
      heute: iso(heute),
      aktion,
      begruendung,
    },
  });
}

return out;

